import java.util.Scanner;

public class lilu {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int totalChars = sc.nextInt();
        int maxBracketLength = 0;
        int totalWords = 0;
        String sequence = sc.next();
        char[] seqChars = sequence.toCharArray();
        boolean inBracket = false;
        int currentSize = 0;
        int tempSize = 0;

        for (int index = 0; index < totalChars; index++) {
            char c = seqChars[index];

            if (c == '(') {
                inBracket = true;
                if (tempSize != 0) {
                    maxBracketLength = Math.max(maxBracketLength, tempSize);
                    tempSize = 0;
                }
            } else if (c == ')') {
                inBracket = false;
            }

            if (inBracket) {
                if (c != '_' && c != '(' && c != ')') {
                    totalWords++;
                }
            } else {
                if (c != '_' && c != '(' && c != ')') {
                    currentSize++;
                    if (index == totalChars - 1) {
                        maxBracketLength = Math.max(maxBracketLength, currentSize);
                    }
                } else {
                    if (currentSize != 0) {
                        maxBracketLength = Math.max(maxBracketLength, currentSize);
                        currentSize = 0;
                    }
                }
            }
        }
        System.out.println(maxBracketLength + " " + totalWords);
    }
}
